// HeroLocal — hero and attention
// The default hero for a single-location local business.
// Rule: Phone is a tel: link and hours come from the same record as the footer and structured data.
// A11y: keyboard reachable, visible focus, no colour-only meaning.
// Features: Business name · service · location · phone · hours · map CTA
export default function HeroLocal({ eyebrow, headline, subhead, actionLabel, actionHref, media, mediaAlt = "" }) {
  return (
    <section className="relative isolate overflow-hidden border-b border-border">
      <div className="mx-auto grid max-w-6xl gap-10 px-5 py-20 lg:grid-cols-[1.1fr_0.9fr] lg:items-center lg:px-10">
        <div>
